const response = $input.first().json;
const attempt = $runIndex + 1;
const plan = $('Prepare request').first().json;
const status = Number.isInteger(response.statusCode) ? response.statusCode : null;
let cid = null;
for (let i = 0; i < $runIndex && i < 3; i++) { try { const prior = $('Evaluate request').first(0, i).json; if (prior.case_id) cid = prior.case_id; } catch {} }
const result = {attempt, status_code: status, case_id: cid, ready: false, retry: false, reason: 'request_failed'};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (status === 200 || status === 202) {
  let body; try { body = JSON.parse(response.body_text); } catch { result.reason = 'invalid_case_response'; return [{json: result}]; }
  const identity = body && body.request;
  const valid = body && uuid.test(body.case_id) && body.approved === false && body.published === false && identity && identity.contract_version === 'report-request-v1' && identity.policy_version === 'v1' && identity.report_schema_version === 'deterministic-comparison-report-v1' && identity.source_file_sha256 === plan.request.source_file_sha256 && identity.source_time_interpretation === plan.request.source_time_interpretation && Object.entries(plan.expected_source_window).every(([k,v]) => identity[k] === v);
  if (!valid || (cid && cid !== body.case_id)) { result.reason = 'case_identity_mismatch'; return [{json: result}]; }
  result.case_id = body.case_id;
  if (status === 200) {
    if (body.state !== 'awaiting_approval' || body.revision !== 1 || body.schema_version !== 'deterministic-comparison-report-v1' || !/^[a-f0-9]{64}$/.test(body.payload_sha256)) { result.reason = 'invalid_stored_revision'; return [{json: result}]; }
    result.ready = true; result.payload_sha256 = body.payload_sha256; result.reason = 'draft_stored'; return [{json: result}];
  }
  if (body.state !== 'received' || body.revision !== null) { result.reason = 'invalid_pending_case'; return [{json: result}]; }
}
const retryable = status === 202 || status === 429 || status === 503 || status === 504;
if (!retryable) { result.reason = status === null ? 'transport_failure_manual_recovery' : 'permanent_HTTP_failure'; return [{json: result}]; }
if (attempt >= 3) { result.reason = 'retry_exhausted_manual_recovery'; return [{json: result}]; }
let seconds = 5 * (2 ** (attempt - 1));
const header = Object.entries(response.headers || {}).find(([k]) => k.toLowerCase() === 'retry-after');
if (header && typeof header[1] === 'string') {
  const raw = header[1].trim();
  if (/^\d+$/.test(raw)) { seconds = Number(raw); }
  else if (/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \d{4} \d{2}:\d{2}:\d{2} GMT$/.test(raw)) { const time = Date.parse(raw); if (Number.isFinite(time)) seconds = Math.max(0, Math.ceil((time - Date.now()) / 1000)); }
}
if (!Number.isFinite(seconds) || seconds > 60) { result.reason = 'retry_after_exceeds_local_bound'; return [{json: result}]; }
result.retry = true; result.wait_seconds = Math.max(1, seconds); result.reason = 'bounded_retry';
return [{json: result}];

const response = $input.first().json;
const plan = $('Prepare request').first().json;
let receipt;
for (let i = 0; i < 3; i++) { try { const value = $('Evaluate request').first(0, i).json; if (value.ready) receipt = value; } catch {} }
let body; try { body = JSON.parse(response.body_text); } catch { throw new Error('Invalid case metadata'); }
if (response.statusCode !== 200 || !receipt || body.case_id !== receipt.case_id || body.state !== 'awaiting_approval' || body.revision !== 1 || body.approved !== false || body.published !== false || body.payload_sha256 !== receipt.payload_sha256 || body.schema_version !== 'deterministic-comparison-report-v1' || !body.request || body.request.source_file_sha256 !== plan.request.source_file_sha256 || body.request.policy_version !== 'v1' || body.request.source_time_interpretation !== plan.request.source_time_interpretation || !Object.entries(plan.expected_source_window).every(([k,v]) => body.request[k] === v) || !Array.isArray(body.audit_events) || body.audit_events.length !== 2) throw new Error('Stored case contract mismatch');
return [{json: {case_id: body.case_id, revision: body.revision, expected_payload_sha256: body.payload_sha256, audit_event_ids: body.audit_events.map(event => event.event_id), request_attempts: receipt.attempt, idempotency_key: plan.idempotency_key, n8n_execution_id: $execution.id ?? null}}];

const item = $input.first();
const response = item.json;
const metadata = $('Validate stored case').first().json;
const headers = Object.fromEntries(Object.entries(response.headers || {}).map(([k,v]) => [k.toLowerCase(),v]));
const length = headers['content-length'];
if (response.statusCode !== 200 || headers['x-report-status'] !== 'unapproved-draft' || headers['x-source-time-interpretation'] !== 'Europe/London-assumed' || !/^[1-9]\d*$/.test(String(length)) || Number(length) > 65536 || !item.binary?.draft_bytes) throw new Error('Invalid unapproved draft response');
return [{json: {...metadata}, binary: item.binary}];

const item = $input.first();
const value = item.json;
if (!/^[a-f0-9]{64}$/.test(value.actual_payload_sha256) || value.actual_payload_sha256 !== value.expected_payload_sha256) throw new Error('Immutable draft hash mismatch');
return [{json: {status: 'unapproved_draft_verified', case_id: value.case_id, revision: value.revision, payload_sha256: value.actual_payload_sha256, audit_event_ids: value.audit_event_ids, request_attempts: value.request_attempts, idempotency_key: value.idempotency_key, n8n_execution_id: value.n8n_execution_id, ai_mode: 'disabled', approval: 'not_enabled', publication: 'not_enabled'}, binary: item.binary}];
